def pickLocale(loc: Any) -> Any:
    return loc if (js.truthy(loc) and js.truthy(own(LABELS, loc))) else "en"


def houseTopic(loc: Any, n: Any) -> Any:
    return js.nullish(
        (
            _v1
            if js.defined(_v1 := own(own(HOUSE_TOPICS, loc), n))
            else own(js.get(HOUSE_TOPICS, "en"), n)
        ),
        "",
    )


def categoryLabel(loc: Any, cat: Any) -> Any:
    c: Any = js.nullish(cat, "")
    label: Any = own(own(REMEDY_CATEGORY_LABELS, loc), c)
    if label is not js.UNDEF:
        return label
    return (
        (js.s(js.upper(js.char_at(c, 0))) + js.replace(js.slice_(c, 1), _RE2, " "))
        if js.test(_RE1, c)
        else c
    )


def planetSummary(loc: Any, name: Any) -> Any:
    n: Any = js.nullish(name, "")
    return js.nullish(
        (
            _v2
            if js.defined(_v2 := own(own(PLANET_SUMMARIES, loc), n))
            else own(js.get(PLANET_SUMMARIES, "en"), n)
        ),
        "",
    )


def houseLordLabel(loc: Any, h: Any) -> Any:
    if js.truthy(js.get(h, "LordLocal")):
        return js.get(h, "LordLocal")
    return lordLabel(loc, js.get(h, "LordEN"), js.get(h, "LordHI"))


def yogaNameLabel(loc: Any, y: Any) -> Any:
    if js.truthy(js.get(y, "NameLocal")):
        return js.get(y, "NameLocal")
    if js.truthy(isDevanagariLocale(loc)) and js.truthy(js.get(y, "NameHI")):
        return js.get(y, "NameHI")
    return js.nullish(js.get(y, "NameEN"), "")


def dashaLordLabel(loc: Any, d: Any) -> Any:
    if js.truthy(js.get(d, "LordLocal")):
        return js.get(d, "LordLocal")
    return lordLabel(loc, js.get(d, "Lord"), js.get(d, "LordHI"))


def doshaNameLabel(label: Any, entry: Any, nameKey: Any) -> Any:
    return _v3 if js.truthy(_v3 := js.get(entry, "NameLocal")) else label(nameKey)


def severityLabel(label: Any, severity: Any) -> Any:
    s: Any = js.nullish(severity, "")
    key: Any = "dosha_severity_" + js.s(s)
    found: Any = label(key)
    return js.or_(found, s)


def areaLabel(label: Any, area: Any) -> Any:
    a: Any = js.nullish(area, "")
    key: Any = "area_" + js.s(a)
    found: Any = label(key)
    return js.or_(found, a)


def anyDoshaPresent(d: Any) -> Any:
    if not js.truthy(d):
        return False
    return (
        (not (not js.truthy(js.get(d, "Mangal")))) or (not (not js.truthy(js.get(d, "KaalSarp"))))
    ) or (not (not js.truthy(js.get(d, "Pitra"))))


