    "\n"
    "/* Graha Sthiti — planet cards grid with glyph images (3-up). */\n"
    ".graha-grid { display: flex; flex-wrap: wrap; gap: 4mm; margin: 5mm 0; }\n"
    ".graha-card {\n"
    "  flex: 0 0 calc(33.333% - 3mm); display: flex; align-items: center; gap: 3mm;\n"
