    "/* The taller scripts pushed a varga table's last row, and the birth almanac, onto pages of their own. */\n"
    ":where(html:lang(te), html:lang(ta), html:lang(kn), html:lang(ml)) .section .divisional-block tbody td,\n"
    ":where(html:lang(te), html:lang(ta), html:lang(kn), html:lang(ml)) .section.short-section table tbody td,\n"
