    "\n"
    "/* Rajyoga donut — pinned colors. */\n"
    ".rajyoga-power { text-align: center; margin: 6mm 0; }\n"
    ".rajyoga-power .rajyoga-pct {\n"
    "  display: inline-block; font-size: 30pt; font-weight: 700; color: var(--as-teal);\n"
