    ".mudda-guidance p { margin: 0.8mm 0; font-size: 10pt; }\n"
    ".mudda-guidance strong { color: var(--as-dorange, #9e2b25); }\n"
    "/* The whole divisional block must NOT be atomic — chart(110mm)+full table is\n"
