def formatGenerated(iso: Any = js.UNDEF) -> Any:
    if not js.truthy(iso):
        return ""
    d: Any = parseTimestamp(iso)
    if js.is_nan(d.get_time()):
        return iso

    def p(n: Any) -> Any:
        return js.pad_start(js.s(n), 2, "0")

    return (
        js.s(d.utc_year())
        + "-"
        + js.s(p(js.add(d.utc_month(), 1)))
        + "-"
        + js.s(p(d.utc_date()))
        + " "
        + js.s(p(d.utc_hours()))
        + ":"
        + js.s(p(d.utc_minutes()))
        + " UTC"
    )


def renderKundliBrihadHtml(data: Any, branding: Any = js.UNDEF) -> Any:
    data = withoutNullItems({**data, "Locale": safeLocale(js.get(data, "Locale"))})
    b: Any = resolveBranding(js.get(data, "Branding"), branding)
    palette: Any = brihadPalette(js.get(data, "Branding"), branding)
    chartAccent: Any = (
        toHex(js.get(palette, "primary"))
        if js.truthy(js.get_optional(palette, "primary"))
        else printableColor(js.get(b, "primaryColor"), DEFAULT_PRIMARY)
    )
    loc: Any = pickLocale(js.get(data, "Locale"))
    label: Any = makeLabeler(LABELS, loc)
    subject: Any = js.nullish(js.get(data, "Subject"), {})
    asc: Any = js.nullish(js.get(data, "Ascendant"), {})
    planets: Any = js.get(data, "Planets") if js.is_array(js.get(data, "Planets")) else []
    houses: Any = js.get(data, "Houses") if js.is_array(js.get(data, "Houses")) else []
    yogas: Any = js.get(data, "Yogas") if js.is_array(js.get(data, "Yogas")) else []
    upcoming: Any = (
        js.get(data, "UpcomingDashas") if js.is_array(js.get(data, "UpcomingDashas")) else []
    )
    remedies: Any = js.get(data, "Remedies") if js.is_array(js.get(data, "Remedies")) else []
    divisionals: Any = (
        js.get(data, "DivisionalCharts") if js.is_array(js.get(data, "DivisionalCharts")) else []
    )
    predictions: Any = (
        js.get(data, "Predictions") if js.is_array(js.get(data, "Predictions")) else []
    )
    citations: Any = js.get(data, "Citations") if js.is_array(js.get(data, "Citations")) else []
    parts: Any = []
    chapters: Any = listOf(js.get(data, "narrative_chapters"))
    chapterByKey: Any = js.Map(js.map_(chapters, (lambda c: [js.get(c, "key"), c])))

    def chapter(key: Any) -> Any:
        ch: Any = chapterByKey.get(key)
        return renderChapter(ch, loc) if js.truthy(ch) else ""

    PART_SENTINEL: Any = "\u0000PART\u0000"

    def partHeading(key: Any) -> Any:
        return (
            js.s(PART_SENTINEL)
            + '<div class="part-banner"><h2 class="part-h2">'
            + esc(label(key))
            + "</h2></div>"
        )

    def mergeSections(heading: Any, *pieces: Any) -> Any:
        present: Any = js.filter_(
            pieces, (lambda p: js.gt(js.length(js.trim(p)), 0) if js.truthy(_v4 := p) else _v4)
        )
        if js.same(js.length(present), 0):
            return ""
        if js.same(js.length(present), 1) and (not js.truthy(heading)):
            return js.get(present, 0)
        h2Re: Any = _RE3

        def innerOf(html: Any) -> Any:
            m: Any = js.exec_(h2Re, html)
            if not js.truthy(m):
                return {"lead": "", "h2": "", "body": html}
            return {
                "lead": js.nullish(js.get(m, 1), ""),
                "h2": js.nullish(js.get(m, 2), ""),
                "body": js.nullish(js.get(m, 3), ""),
            }

        first: Any = innerOf(js.get(present, 0))
        h2: Any = esc(heading) if js.truthy(heading) else js.get(first, "h2")
        merged: Any = (
            '<section class="section">\n'
            + js.s(js.get(first, "lead"))
            + "<h2>"
            + js.s(h2)
            + "</h2>"
            + js.s(js.get(first, "body"))
        )
        for i in range(1, js.length(present)):
            part: Any = innerOf(js.get(present, i))
            if js.truthy(js.get(part, "h2")):
                merged = js.add(
                    merged, (('\n<h3 class="merged-sub">') + js.s(js.get(part, "h2")) + "</h3>")
                )
            merged = js.add(merged, js.get(part, "body"))
        merged = js.add(merged, ("\n</section>"))
        return merged

    parts.append(
        (
            '<section class="cover">\n'
            + js.s(coverBrandingHtml(b))
            + ("\n<h1>")
            + esc(label("title_brihad"))
            + ('</h1>\n<div class="subtitle">')
            + esc(label("subtitle_brihad"))
            + ('</div>\n<div class="subject">')
            + esc(js.get(subject, "Name"))
            + ('</div>\n<div class="meta">\n')
            + esc(label("born"))
            + " "
            + esc(js.get(subject, "BirthDate"))
            + " "
            + esc(label("at"))
            + " "
            + esc(js.get(subject, "BirthTime"))
            + "<br>\n"
            + esc(js.get(subject, "BirthPlace"))
            + ('\n</div>\n<div class="generated">\n')
            + esc(label("generated"))
            + " "
            + esc(formatGenerated(js.get(data, "GeneratedAt")))
            + ("\n</div>\n</section>")
        )
    )

    def _fn7() -> Any:
        ascNak: Any = esc(js.get(asc, "nakshatra"))

        def _fn5(p: Any) -> Any:
            pl: Any = js.nullish(js.get(p, "placement"), {})
