    def spliceBanner(sectionHtml: Any, banner: Any) -> Any:
        gt: Any = js.index_of(sectionHtml, ">")
        if js.same(gt, -1):
            return js.add(banner, sectionHtml)
        return ((js.s(js.slice_(sectionHtml, 0, js.add(gt, 1))) + "\n") + js.s(banner)) + js.s(
            js.slice_(sectionHtml, js.add(gt, 1))
        )

