        if js.starts_with(html, PART_SENTINEL):
            pendingBanner = js.slice_(html, js.length(PART_SENTINEL))
            continue
        if js.truthy(pendingBanner):
            parts.append(spliceBanner(html, pendingBanner))
            pendingBanner = ""
